def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    op_def = 0
    for _, o in history:
        if o == 'D':
            op_def += 1
    if op_def * 2 > n:
        return 'D'
    last_opp = history[-1][1]
    return 'D' if last_opp == 'D' else 'C'
